setup(build) {
  const SERVER_SRC = path.resolve(__dirname, "../../server/src");
  const resolveToShim = (shimFile) => (args) => {
    if (!args.resolveDir) return;
    const abs = path.resolve(args.resolveDir, args.path).replace(/\.[jt]sx?$/, "");
    const target = path.join(SERVER_SRC, shimFile).replace(/\.[jt]sx?$/, "");
    if (abs === target) return { path: path.join(SHIMS, shimFile + ".ts") };
  };
  // Intercept server/src/middleware/logger — any relative or absolute import
  build.onResolve({ filter: /logger/ }, resolveToShim("middleware/logger"));
  // Intercept server/src/version — uses createRequire("../package.json") which fails in CF
  build.onResolve({ filter: /version/ }, resolveToShim("version"));
},
